import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Card, Container, Row, Col } from 'react-bootstrap';

const UserList = () => {
  const [users, setUsers] = useState([]);

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const response = await axios.get('https://requestuser.free.beeceptor.com');
        console.log('Dados recebidos:', response.data); // Adicione isto para ver a resposta no console
        // Garantir que users seja um array
        if (Array.isArray(response.data)) {
          setUsers(response.data);
        } else {
          console.error('Dados recebidos não são um array:', response.data);
          setUsers([]); // Define como um array vazio em caso de erro
        }
      } catch (error) {
        console.error('Erro ao buscar os usuários:', error);
      }
    };

    fetchUsers(); // Chama a função para buscar os dados quando o componente é montado
  }, []);

  return (
    <Container>
      <Row>
        {users.map((user, index) => (
          <Col key={index} sm={12} md={6} lg={4}>
            <Card className="my-3">
              <Card.Body>
                <Card.Title>{user.nome}</Card.Title>
                <Card.Subtitle className="mb-2 text-muted">{user.telefone}</Card.Subtitle>
                <Card.Text>
                  Data de Nascimento: {user.dataNascimento}
                </Card.Text>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </Container>
  );
};

export default UserList;
